#include <iostream>
#include <vector>
#include <string>
#include <set>
#include <map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string target;
    cin >> target;
    long long k;
    cin >> k;
    vector<string> dead(k);
    for (int i = 0; i < k; i++) cin >> dead[i];

    set<string> blocked(dead.begin(), dead.end());
    if (blocked.count("0000")) {
        cout << -1 << "\n";
    } else {
        map<string, int> dist;
        dist["0000"] = 0;
        vector<string> queue = {"0000"};
        for (size_t q = 0; q < queue.size(); q++) {
            string state = queue[q];
            for (int i = 0; i < 4; i++) {
                for (int step : {1, 9}) {
                    string next = state;
                    next[i] = (char)('0' + (state[i] - '0' + step) % 10);
                    if (!dist.count(next) && !blocked.count(next)) {
                        dist[next] = dist[state] + 1;
                        queue.push_back(next);
                    }
                }
            }
        }
        cout << (dist.count(target) ? dist[target] : -1) << "\n";
    }

    return 0;
}

